#!/usr/bin/env bash
# Cross-repo Fusion acceptance seam. Unlike the core dapp fixture test, this
# requires and consumes a receipt generated by robotmoney-frontend.
set -euo pipefail

fail() { echo "fusion-cross-repo: $*" >&2; exit 1; }

: "${FUSION_FRONTEND_RECEIPT_FILE:?point to a frontend-generated receipt artifact}"
: "${FUSION_FRONTEND_RECEIPT_URL:?set the stable public URL serving those exact bytes}"
: "${FUSION_RMPC_CONFIG:?set FUSION_RMPC_CONFIG}"
: "${FUSION_RECEIPT_ADDRESS:?set FUSION_RECEIPT_ADDRESS}"
: "${FUSION_RPC_URL:?set FUSION_RPC_URL}"
: "${FUSION_RECORD_CMD:?set FUSION_RECORD_CMD (the Safe recording command the submit worker hands the verified bytes to; issue 1888)}"
# INV-4 witnesses. Required, not optional: "recording changed no allocation
# state" is an assertion this test makes, and an unset address would turn it into a
# silent skip (AC-CORE-04, AC-E2E-03, AC-E2E-04).
: "${FUSION_GOVERNANCE_ADDRESS:?set FUSION_GOVERNANCE_ADDRESS (RouterGovernance)}"
: "${FUSION_ROUTER_ADDRESS:?set FUSION_ROUTER_ADDRESS (PortfolioRouter)}"
# AC-CORE-04 names "vault balances, router weights, and proposal count", and
# AC-E2E-03 repeats them. The proposal count no longer exists (issue 1698
# removed propose/vote/execute from RouterGovernance; see lib/inv4.sh). Weights
# alone would miss an asset movement, so the mapped vaults are required too:
# comma-separated rmUSDC,rmPROTO,rmAGENT,rmRWA addresses from the 2.7 manifest.
: "${FUSION_VAULT_ADDRESSES:?set FUSION_VAULT_ADDRESSES (comma-separated mapped vault addresses)}"

RMPC_BIN="${RMPC_BIN:-rmpc}"
CAST_BIN="${CAST_BIN:-cast}"
command -v jq >/dev/null || fail "jq is required"

# T10: ONE INV-4 witness reader, shared with devnet-acceptance.sh. This script
# used to read only `totalAssets` (no `totalSupply`) over an unbounded window,
# so it and its sibling could disagree about the same chain.
FUSION_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/lib" && pwd)"
# shellcheck source=lib/inv4.sh
source "$FUSION_LIB_DIR/inv4.sh"

# T25: the alert path is validated the way rmpc/cast are, not discovered at the
# moment it is needed. Runbook §5.5 claims both harnesses page.
if [[ -n "${FUSION_ALERT_WEBHOOK:-}" ]]; then
  command -v curl >/dev/null || fail "FUSION_ALERT_WEBHOOK is set but curl is not on PATH: pages would be silently dropped"
  command -v jq   >/dev/null || fail "FUSION_ALERT_WEBHOOK is set but jq is not on PATH: pages would be silently dropped"
else
  echo "fusion-cross-repo: WARNING FUSION_ALERT_WEBHOOK is unset — failures will be stderr-only and will page nobody" >&2
fi

EVIDENCE_DIR="${FUSION_EVIDENCE_DIR:-}"
record() { # record <name> <content>
  [[ -n "$EVIDENCE_DIR" ]] || return 0
  mkdir -p "$EVIDENCE_DIR"
  printf '%s\n' "$2" >"$EVIDENCE_DIR/$1"
}

verify="$("$RMPC_BIN" receipt -c "$FUSION_RMPC_CONFIG" verify \
  --receipt-file "$FUSION_FRONTEND_RECEIPT_FILE")" || fail "frontend receipt failed core verification"
receipt_id="$(jq -er '.receipt_id' <<<"$verify")"
digest="$(jq -er '.payload_digest' <<<"$verify")"
record "core-verify-file.json" "$verify"

# AC-CORE-02 and AC-E2E-02 both require rmpc to fetch the STABLE PUBLIC URL and
# verify what is actually served there. `--receipt-file` reads local bytes while
# the URL is still what gets anchored as payloadUri (cli.rs: "The URL is still
# what gets anchored"), so verifying only the file would let a stale cache, a
# republish or a wrong session produce an on-chain (payloadDigest, payloadUri)
# pair the public URL does not reproduce — with this script still reporting the
# core_verify stage as passed. Fetch it, and prove the two agree.
verify_url="$("$RMPC_BIN" receipt -c "$FUSION_RMPC_CONFIG" verify \
  --receipt-url "$FUSION_FRONTEND_RECEIPT_URL")" \
  || fail "the bytes served at $FUSION_FRONTEND_RECEIPT_URL failed core verification"
record "core-verify-url.json" "$verify_url"
url_receipt_id="$(jq -er '.receipt_id' <<<"$verify_url")"
url_digest="$(jq -er '.payload_digest' <<<"$verify_url")"
[[ "$url_digest" == "$digest" ]] \
  || fail "the URL being anchored serves different bytes than the file being submitted \
(url payload_digest $url_digest, file payload_digest $digest)"
[[ "$url_receipt_id" == "$receipt_id" ]] \
  || fail "the URL being anchored derives receipt_id $url_receipt_id, file derives $receipt_id"

# T15, AC-FMT-03. THE WEIGHTS ARE THE ALLOCATION. A receipt with no weights
# array, or one that does not total 10000 bps over the four buckets, cannot
# carry a recommendation, and runbook §5.5 says an absent `weights` array is a
# FAILED assertion, never a skipped one. Issue 1698 deleted the draft step that
# used to check this, so it is checked here on the bytes being submitted,
# before anything is anchored.
jq -e '[.weights[]?.weight_bps] | length == 4 and add == 10000' \
  "$FUSION_FRONTEND_RECEIPT_FILE" >/dev/null 2>&1 \
  || fail "the receipt must carry four bucket weights totalling exactly 10000 bps: \
$(jq -c '[.weights[]?.weight_bps]' "$FUSION_FRONTEND_RECEIPT_FILE" 2>/dev/null || echo '<no weights array>')"

IFS=',' read -r -a VAULTS <<<"$FUSION_VAULT_ADDRESSES"
(( ${#VAULTS[@]} > 0 )) || fail "FUSION_VAULT_ADDRESSES is empty"

witnesses() {
  inv4_witnesses "$CAST_BIN" "$FUSION_RPC_URL" "$FUSION_GOVERNANCE_ADDRESS" \
    "$FUSION_ROUTER_ADDRESS" "${VAULTS[@]}" || true
}

# THE INV-4 WINDOW BRACKETS THE WRITE STAGES, and opens here rather than at
# script start (T10, matching ddbbe895 on the sibling). A mapped vault with a
# live yield adapter accrues on its own; comparing the end of a long run against
# a snapshot taken before verification would report accrual as an INV-4 breach.
# The comparison itself stays exact equality — only the window narrows.
witnesses_before="$(witnesses)"
inv4_unreadable "$witnesses_before" \
  && fail "INV-4 witnesses are not readable: refusing to run a gate whose blocker \
assertion could only compare one absence against another — $witnesses_before"
record "inv4-witnesses-before.txt" "$witnesses_before"

# The worker's own JSON goes to the evidence dir and to stderr, NOT to this
# script's stdout: stdout is the single evidence document this script produces,
# and a second JSON object on it makes every downstream `jq` read the wrong one.
worker_out="$(FUSION_RECEIPT_FILE="$FUSION_FRONTEND_RECEIPT_FILE" \
  FUSION_RECEIPT_URL="$FUSION_FRONTEND_RECEIPT_URL" \
  FUSION_MAX_ATTEMPTS="${FUSION_MAX_ATTEMPTS:-5}" \
  "$(dirname "$0")/submit-receipt-worker.sh")" \
  || fail "the submit worker did not anchor the receipt"
record "submit-worker.json" "$worker_out"
printf '%s\n' "$worker_out" >&2

# INV-4 "after" witnesses, closing the window opened before the submit. Recording
# is signalling-only, so nothing here may have moved. Issue 1698: there is no
# draft step. A receipt reaches the router only through
# RouterGovernance.applyReceipt (publish-contracts govern row apply-receipt),
# which releases it and sets the weights in one call. That apply moves the
# router weights by design (issue 1849), so the window closes HERE, immediately
# before it.
witnesses_after="$(witnesses)"
record "inv4-witnesses-after.txt" "$witnesses_after"
inv4_unreadable "$witnesses_after" \
  && fail "INV-4 witnesses became unreadable after the write stages, so NOTHING was \
compared — $witnesses_after"

if [[ "$witnesses_after" != "$witnesses_before" ]]; then
  fail "INV-4 violated: an allocation-state witness moved across record
$(diff <(printf '%s' "$witnesses_before") <(printf '%s' "$witnesses_after") || true)
$INV4_ACCRUAL_NOTE"
fi

# The release is a governance action. The Safe applies the receipt through the
# timelock, run by `bun scripts/stage/core-stack.ts governance apply` (publish
# contracts govern, row apply-receipt), which releases the receipt and sets its
# weights in one RouterGovernance.applyReceipt call. Issue 1849: row
# release-receipt is refused since issue 1831, because a bare release burns the
# receipt. A single keystore never releases a receipt: after handover no EOA
# holds the receipt contract's admin role, so a direct send would only revert.
# Run the govern row first, then run this script with FUSION_SKIP_RELEASE=1, or
# set FUSION_GOVERN_CMD so this script runs it. The payload is the frontend
# receipt file: it is the file that was submitted, and the URL was proved above
# to serve the same digest. The row checks it against the anchored digest
# before it sends anything.
#
# T29: IDEMPOTENT, BECAUSE THIS SCRIPT IS THE AC-E2E-05 SEAM AND IS RUN TWICE.
# A receipt applies once: a second apply is refused (already released), and
# under `set -euo pipefail` that would abort the script at this line, so the
# evidence JSON after it would never be written and a real regression between
# the two runs would be invisible behind the false failure. Read the state
# first, which is also what an operator does. The post-condition read below
# stays the actual assertion.
release_action="sent"
if [[ "${FUSION_SKIP_RELEASE:-0}" == "1" ]]; then
  release_action="skipped_external_ceremony"
else
  already_released="$("$CAST_BIN" call "$FUSION_RECEIPT_ADDRESS" 'isReleased(bytes32)(bool)' \
    "$receipt_id" --rpc-url "$FUSION_RPC_URL")" \
    || fail "could not read isReleased() before the apply"
  already_released="$(tr -d '[:space:]' <<<"$already_released")"
  if [[ "$already_released" == "true" ]]; then
    release_action="already_released"
    echo "fusion-cross-repo: receipt $receipt_id is already released; no second apply" >&2
  else
    : "${FUSION_GOVERN_CMD:?the apply goes through the real Safe and the timelock: set FUSION_GOVERN_CMD to the govern apply command (bun scripts/stage/core-stack.ts governance apply), or run it first and set FUSION_SKIP_RELEASE=1}"
    # shellcheck disable=SC2086 # the command is a word list by contract
    apply_out="$($FUSION_GOVERN_CMD --receipt-id "$receipt_id" --payload "$FUSION_FRONTEND_RECEIPT_FILE")" \
      || fail "the govern apply-receipt row failed for receipt $receipt_id"
    record "apply-rows.json" "$apply_out"
    grep '^{' <<<"$apply_out" | jq -s -e \
      'length >= 1 and all(.row == "apply-receipt") and all(.status == 1 or .status == "0x1") and all(.txHash | test("^0x[0-9a-fA-F]{64}$"))' \
      >/dev/null 2>&1 \
      || fail "the govern apply printed no apply-receipt row with a tx hash and status 1 for receipt $receipt_id: $(head -c 300 <<<"$apply_out")"
  fi
fi

released="$("$CAST_BIN" call "$FUSION_RECEIPT_ADDRESS" 'isReleased(bytes32)(bool)' \
  "$receipt_id" --rpc-url "$FUSION_RPC_URL")"
[[ "$released" == "true" ]] || fail "receipt is anchored but not released"

# THE APPLY-PATH BINDING (issue 1698). A receipt moves router weights only
# through RouterGovernance.applyReceipt, which releases a receipt recorded on
# the weight setter's own register (`receipts()`). The apply above went through
# that path, so assert the weight setter reads THIS register: the receipt just
# anchored is one the apply path can act on. An eth_call: nothing moves.
bound="$("$CAST_BIN" call "$FUSION_GOVERNANCE_ADDRESS" 'receipts()(address)' \
  --rpc-url "$FUSION_RPC_URL")" || fail "could not read receipts() on the weight setter $FUSION_GOVERNANCE_ADDRESS"
bound="$(tr -d '[:space:]' <<<"$bound")"
[[ "${bound,,}" == "${FUSION_RECEIPT_ADDRESS,,}" ]] \
  || fail "the weight setter applies receipts from $bound, not from the receipt contract \
$FUSION_RECEIPT_ADDRESS that holds this receipt"
record "apply-path-receipt-contract.txt" "$bound"

witnesses_json() { # `key=value` lines -> {"key":"value"}
  jq -Rn '[inputs | select(length>0) | (index("=")) as $i |
           {key:.[0:$i], value:.[$i+1:]}] | from_entries'
}

jq -n --arg receipt_id "$receipt_id" --arg payload_digest "$digest" \
  --arg receipt_url "$FUSION_FRONTEND_RECEIPT_URL" --arg url_digest "$url_digest" \
  --arg release_action "$release_action" --arg receipt_contract "$bound" \
  --argjson witnesses_before "$(witnesses_json <<<"$witnesses_before")" \
  --argjson witnesses_after "$(witnesses_json <<<"$witnesses_after")" \
  '{ok:true,
    stages:["frontend_artifact","core_verify_file","core_verify_url","receipt_weights","submit",
            ("release:" + $release_action),"apply_path_bound","inv4_unchanged"],
    release:{action:$release_action,
             broadcast:($release_action == "sent")},
    apply_path:{weight_setter_receipt_contract:$receipt_contract},
    receipt_id:$receipt_id,payload_digest:$payload_digest,
    anchored_url:{url:$receipt_url,payload_digest:$url_digest,matches_submitted_bytes:true},
    inv4:{witnesses_before:$witnesses_before,
          witnesses_after:$witnesses_after,
          window:"immediately before submit .. immediately before the apply",
          unchanged:true}}'
